const kRawHTML: unique symbol = /* @__PURE__ */ Symbol("h3.rawHTML");

function isRawHTML(value: unknown): value is RawHTML {
  return (
    typeof value === "object" &&
    value !== null &&
    (value as { [kRawHTML]?: unknown })[kRawHTML] === true
  );
}

// RFC 9110 reason phrases for the statuses `noContent` and `redirect` are meant for.
// Any other status gets no phrase rather than one that belongs to a different code.
const STATUS_TEXT: Record<number, string> = {
  204: "No Content",
  301: "Moved Permanently",
  302: "Found",
  303: "See Other",
  307: "Temporary Redirect",
  308: "Permanent Redirect",
};

const HTML_ESCAPES: Record<string, string> = {
  "&": "&amp;",
  '"': "&quot;",
  "'": "&#39;",
  "<": "&lt;",
  ">": "&gt;",
};

/** HTML-escape the special characters `& < > " '`. */
function escapeHtml(str: string): string {
  return str.replace(/[&"'<>]/g, (c) => HTML_ESCAPES[c]!);
}

